return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Catalan','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-01 17:26+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'ca','plural-forms'=>'nplurals=2; plural=n != 1;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['Lingua Forge'=>'Llengua Forge','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','Multilingual routing, SEO meta tags, and AI content tools for WordPress. Combines language detection, URL routing, hreflang, meta descriptions, and AI-powered excerpt, meta, and translation features.'=>'Enrutament multilingüe, etiquetes meta SEO i eines de contingut amb IA per a WordPress. Combina detecció de llengua, enrutament d\'URL, hreflang, descripcions meta i funcions d\'extracte, meta i traducció amb IA.','Uli Hake'=>'Uli Hake','https://lingua-forge.com'=>'https://lingua-forge.com','Translate'=>'Tradueix','Lingua Forge — Quick Translate'=>'Lingua Forge — Traducció ràpida','Informative'=>'Informatiu','Persuasive'=>'Persuasiu','Storytelling'=>'Narració','Technical'=>'Tècnic','Conversational'=>'Conversacional','Permission denied.'=>'Permís denegat.','Cannot determine target language from slug.'=>'No es pot determinar l\'idioma de destinació a partir de l\'slug.','Invalid post type.'=>'Tipus de publicació no vàlid.','Invalid or primary language.'=>'Idioma no vàlid o principal.','Template not found or not stored in the database.'=>'Plantilla no trobada o no emmagatzemada a la base de dades.','Template has no content.'=>'La plantilla no té contingut.','No internal links found to update.'=>'No s\'han trobat enllaços interns per actualitzar.','%d link updated.'=>'%d enllaç actualitzat.' . "\0" . '%d enllaços actualitzats.','No language-specific template parts found to map.'=>'No s\'han trobat parts de plantilla específiques d\'idioma per mapar.','No template part references needed updating.'=>'No cal actualitzar referències de parts de plantilla.','%d part reference updated.'=>'S\'ha actualitzat la referència de %d part.' . "\0" . 'S\'han actualitzat %d referències de parts.','Invalid language.'=>'Idioma no vàlid.','Template part not found or not stored in the database.'=>'Part de plantilla no trobada o no emmagatzemada a la base de dades.','Template part has no content.'=>'La part de plantilla no té contingut.','No navigation references needed updating.'=>'No cal actualitzar referències de navegació.','%d navigation reference updated.'=>'S\'ha actualitzat la referència de navegació %d.' . "\0" . 'S\'han actualitzat %d referències de navegació.','No AI provider configured.'=>'Cap proveïdor d\'IA configurat.','Missing pattern name or language.'=>'Falta el nom del patró o l\'idioma.','Pattern not found.'=>'Patró no trobat.','Pattern has no content to translate.'=>'El patró no té contingut per traduir.','AI provider returned an empty response.'=>'El proveïdor d\'IA ha retornat una resposta buida.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'El patró ha estat traduït i desat. Copia el contingut al teu publicació CPT mitjançant l\'inseridor de patrons de l\'editor de blocs o utilitza\'l com a punt de partida per a un bloc reutilitzable.','Invalid template type.'=>'Tipus de plantilla no vàlid.','Template "%s" already exists.'=>'La plantilla "%s" ja existeix.','"%s" created.'=>'"%s" creat.','Invalid template part.'=>'Part de plantilla no vàlida.','Template part "%s" already exists.'=>'Part de plantilla "%s" ja existeix.','"%1$s" created. %2$d template updated.'=>'"%1$s" creat. %2$d plantilla actualitzada.' . "\0" . '"%1$s" creat. %2$d plantilles actualitzades.','Page'=>'Pàgina','Single'=>'Simple','Search'=>'Cerca','Search Results'=>'Resultats de la cerca','Archive'=>'Arxiu','Front Page'=>'Pàgina principal','Single: %s'=>'Singular: %s','Single %s'=>'Singular %s','Archive: %s'=>'Arxiu: %s','%s Archive'=>'%s Arxiu','No source content found to translate.'=>'No s\'ha trobat contingut d\'origen per traduir.','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Traduit. Revisió a l\'Editor del lloc — els enllaços interns, les URL de navegació i els slugs de les plantilles no s\'actualitzen automàticament.','Navigation not found.'=>'Navegació no trobada.','Navigation has no content to translate.'=>'La navegació no té contingut per traduir.','"%1$s %2$s" saved.'=>'"%1$s %2$s" guardat.','Translate page…'=>'Tradueix la pàgina…','Generate content…'=>'Genera contingut…','AI Behaviour Preset'=>'Predefinit de comportament de IA','Custom'=>'Personalitzat','Global default (%s)'=>'Per defecte global (%s)','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'Sobreescriu el predefinit de IA per a la traducció i la generació de contingut en aquesta pàgina. Les instruccions personalitzades globals (Configuració → Comportament) sempre s\'afegeixen a cada sol·licitud independentment d\'aquesta selecció.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Sobreescriu el predefinit de IA per a la traducció i la generació de contingut en aquesta pàgina. Totes les altres funcions sempre utilitzen el predefinit global.','Close'=>'Tanca','Translate missing'=>'Falta traducció','From'=>'De','Retranslate'=>'Retradueix','Translating…'=>'Traduint…','Retranslating…'=>'Retraduint…','✓ Done'=>'✓ Fet','Error'=>'Error','Navigation posts are translated via the Router tab, not this button.'=>'Les publicacions de navegació es tradueixen a través de la pestanya Router, no amb aquest botó.','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'Crear traduccions per al tipus de publicació "%s" requereix una integració activa. Assegureu-vos que la integració requerida està instal·lada i activa.','No %s version found in this translation group.'=>'No s\'ha trobat cap versió de %s en aquest grup de traduccions.','AI Usage'=>'Ús de IA','Today'=>'Avui','Last 7 days'=>'Els últims 7 dies','Last 30 days'=>'Els últims 30 dies','All time'=>'Tot el temps','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are deliberately excluded so they don\'t skew the totals. The underlying table aggregates daily — pick a window below to view it.'=>'Consum de tokens agrupat per funció, proveïdor i model. Registrat en cada trucada d\'IA exitosa; els pings de Prova de connexió s\'exclouen deliberadament perquè no distorsionin els totals. La taula subjacent s\'agrupa diàriament — selecciona una finestra a continuació per veure-la.','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Encara no s\'ha registrat cap ús d\'IA. Un cop un editor executa una traducció, genera una meta descripció o utilitza qualsevol altra funció d\'IA, els totals apareixeran aquí.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'No s\'ha registrat cap ús d\'IA en la finestra seleccionada (%s). Selecciona un rang més ampli a dalt.','Feature'=>'Funció','Provider'=>'Proveïdor','Model'=>'Model','Requests'=>'Sol·licituds','Input tokens'=>'Tokens d\'entrada','Output tokens'=>'Tokens de sortida','Total tokens'=>'Tokens totals','Total'=>'Total','API Keys'=>'Claus API','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'Les claus API s\'encripten amb AES-256-CBC abans de ser emmagatzemades a la base de dades de WordPress. El secret d\'encriptació es deriva dels salts d\'autenticació de WordPress (wp-config.php), de manera que les claus en text pla mai no toquen la base de dades.','API Key'=>'Clau API','Paste your API key…'=>'Enganxa la teva clau API…','✓ Configured'=>'✓ Configurat','✗ Not configured'=>'✗ No configurat','Test connection'=>'Prova de connexió','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Deixa en blanc per mantenir la clau existent. Introdueix un valor nou per substituir-la.','Remove stored key'=>'Elimina la clau emmagatzemada','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Actualment, aquesta clau és proporcionada per un servidor %s i no es pot eliminar aquí. Introdueix una nova clau a dalt per substituir-la amb un valor de base de dades.','environment variable'=>'variable d\'entorn','PHP constant'=>'constant PHP','Alternative (server-side):'=>'Alternativa (del costat del servidor):','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'També pots definir claus com a constants o variables d\'entorn (per exemple, en wp-config.php). Aquestes fonts s\'utilitzen automàticament com a fallback quan no s\'emmagatzema cap clau de base de dades.','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'Per utilitzar un secret de xifratge personalitzat (en lloc del valor derivat wp_salt), afegeix això a wp-config.php:','Unknown provider.'=>'Proveïdor desconegut.','No API key configured for this provider.'=>'No hi ha cap clau API configurada per a aquest proveïdor.','Could not instantiate the provider.'=>'No s\'ha pogut instanciar el proveïdor.','Provider returned no text. Check the WordPress error log for the detailed failure reason.'=>'El proveïdor no ha retornat cap text. Comprova el registre d\'errors de WordPress per a la raó detallada de la fallada.','Behavior'=>'Comportament','Block Editor'=>'Editor de blocs','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge restringeix dues funcions de Gutenberg per defecte per mantenir la coherència del comportament editorial entre idiomes. Opta aquí quan necessitis totes les capacitats de Gutenberg / FSE.','Block locking'=>'Bloqueig de blocs','Allow editors to lock individual blocks'=>'Permet als editors bloquejar blocs individuals','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Reactiva canLockBlocks de Gutenberg. Útil per a plantilles editorials que necessiten evitar que els col·laboradors moguin o eliminin blocs específics.','Template mode'=>'Mode de plantilla','Allow Gutenberg template-editing mode on post screens'=>'Permet el mode d\'edició de plantilles de Gutenberg a les pantalles de publicació','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'Reactiva supportsTemplateMode. Clau per als fluxos de treball de Full-Site-Editing on les sobrescripcions de plantilla a nivell de publicació són intencionades.','Compliance Preset'=>'Predefinit de compliment','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Mode de preservació estricta per a contingut legal, regulador, mèdic o tècnic. Quan està activat, cada funció d\'IA utilitza una temperatura de mostreig baixa i afegeix l\'addenda a continuació al seu sistema de prompt — la terminologia, els números d\'article, les unitats, els noms de marca i el llenguatge regulador es preserven textualment en lloc de parafrasejar.','Global AI preset'=>'Predefinit global d\'IA','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, per funció','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'Estableix el comportament predeterminat de l\'IA per a totes les funcions a tot el lloc. Els publicacions individuals poden substituir això per Traducció i Generació de contingut a través de la caixa meta de Lingua Forge.','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'El mode estàndard utilitza la temperatura ajustada de cada funció: Traducció T=0.2 (precís), Traducció ràpida T=0.4, Generador de contingut T=0.6 (creatiu). Els altres predefinits apliquen una temperatura fixa única a totes les funcions.','Technical / Scientific instructions'=>'Instruccions tècniques / científiques','Legal / Compliance instructions'=>'Instruccions legals / de compliment','Creative / Marketing instructions'=>'Instruccions creatives / de màrqueting','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Deixa en blanc per utilitzar el valor predeterminat integrat. Esborrar una sobrescriptura desada restableix el valor predeterminat a la propera gravació.','View built-in default'=>'Veure el valor predeterminat integrat','Translation Memory'=>'Memòria de traducció','Cache translated equivalents at the block level so reusable content (shared footers, sidebars, accordions, boilerplate-heavy legal sections) does not pay an API call every time. When enabled, the translation flow parses each post into blocks, looks each block up in the cache, and sends only uncached blocks to the AI in a single batched request. Glossary edits and Compliance preset changes automatically invalidate affected cached translations. View statistics and clear the cache under Maintenance.'=>'Emmagatzema en cache els equivalents traduïts a nivell de bloc perquè el contingut reutilitzable (peus de pàgina compartits, barres laterals, acords, seccions legals amb molta plantilla) no pagui una trucada API cada vegada. Quan està activat, el flux de traducció analitza cada publicació en blocs, busca cada bloc a la cache i envia només els blocs no emmagatzemats en cache a l\'IA en una sol·licitud agrupada. Les edicions del glossari i els canvis en el predefinit de compliment invaliden automàticament les traduccions en cache afectades. Veure estadístiques i esborrar la cache a Manteniment.','Enable block-level translation cache reuse across posts'=>'Permet reutilitzar la cache de traducció a nivell de bloc entre publicacions','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'Actualment s\'ignora per a publicacions que utilitzen espais reservats d\'atribut de comentari de bloc (campos wp:details, resum, etc.) — passen a la ruta de traducció de trucada única existent.','General'=>'General','Light'=>'Lleuger','Meta Description, Excerpt Generator'=>'Meta Descripció, Generador d\'Excerpts','Quality'=>'Qualitat','Translation, Content Generator'=>'Traducció, Generador de contingut','Active Provider'=>'Proveïdor actiu','Currently inherited from the %s constant. Selecting a value here will override it.'=>'Actualment heretat de la constant %s. Seleccionar un valor aquí el substituirà.','Models'=>'Models','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'Les funcions es agrupen en dues categories. Introdueix l\'identificador exacte del model per a cada categoria i proveïdor. Deixa un camp en blanc per utilitzar el predeterminat integrat (mostrat com a espai reservat). Només s\'invoca el model del proveïdor actiu en temps d\'execució — configura els altres prèviament si planejes canviar.','active'=>'actiu','overridden'=>'sobreescrit','Tip: to reset a model to the built-in default, clear the field and save.'=>'Consell: per restablir un model al predeterminat integrat, esborra el camp i desa.','Glossary'=>'Glosari','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Taula de terminologia gestionada per l\'usuari per parelles de llengües. Les entrades s\'afegeixen a la sol·licitud del sistema de traducció perquè la IA utilitzi termes preferits de manera consistent — crític per al vocabulari del domini ("kWp", "PPA", "punt d\'interconnexió"), noms de marca que no s\'han de traduir, i frases regulatòries estàndard. Els camps de llengua són opcionals: deixa en blanc "Llengua d\'origen" per aplicar l\'entrada independentment de la llengua de la qual tradueixes; deixa en blanc "Llengua de destinació" per aplicar-la a totes les llengües de destinació a la vegada.','Glossary entry added.'=>'Entrada de glossari afegida.','Glossary entry removed.'=>'Entrada de glossari eliminada.','Could not add entry: source term and target term are required.'=>'No s\'ha pogut afegir l\'entrada: cal el terme d\'origen i el terme de destinació.','Could not save the glossary entry.'=>'No s\'ha pogut desar l\'entrada del glossari.','Source language'=>'Llengua d\'origen','— Any —'=>'— Qualsevol —','Target language'=>'Llengua de destinació','— Any target —'=>'— Qualsevol destinació —','Filter'=>'Filtre','Reset'=>'Restableix','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'Cap entrada de glossari coincideix amb el filtre actual. Esborra el filtre per veure totes les entrades, o afegeix-ne una de nova a continuació.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'Encara no hi ha entrades de glossari. Afegeix-ne una a continuació per començar a aplicar terminologia en les traduccions.','Source term'=>'Termes d\'origen','Target term'=>'Termes de destinació','Source lang'=>'Llengua d\'origen','Target lang'=>'Llengua de destinació','Notes'=>'Notes','any'=>'qualsevol','Delete this glossary entry?'=>'Voleu eliminar aquesta entrada de glossari?','Delete'=>'Eliminar','Add new entry'=>'Afegeix una nova entrada','The phrase as it appears in the source text.'=>'La frase tal com apareix en el text d\'origen.','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'Com hauria de aparèixer en la traducció. Escriu el mateix valor que el terme d\'origen per instruir la IA a conservar-lo literalment.','— Any source language —'=>'— Qualsevol llengua d\'origen —','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Deixa en blanc per a noms de marca i termes independents de la llengua que s\'han d\'aplicar independentment de la llengua de la qual tradueixes.','— Any target language —'=>'— Qualsevol llengua de destinació —','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Deixa en blanc per aplicar aquesta entrada a totes les llengües de destinació — ideal per a noms de marca, abreviatures i termes que s\'han de preservar literalment en totes les traduccions.','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Context opcional per a editors (p. ex. "ASIC = Circuit Integrat Específic per a Aplicacions; conservar en anglès en contexts tècnics").','Add entry'=>'Afegeix entrada','Limits'=>'Límits','Authors and above (edit_published_posts)'=>'Autors i més (edit_published_posts)','Contributors and above — default (edit_posts)'=>'Col·laboradors i més — per defecte (edit_posts)','Editors and above (edit_others_posts)'=>'Editors i més (edit_others_posts)','Administrators only (manage_options)'=>'Només administradors (manage_options)','AI Limits & Security'=>'Límits i seguretat de la IA','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Limita l\'ús de la IA que pot generar el lloc i restringeix quins rols d\'usuari poden activar trucades de IA de pagament. S\'ubica per sobre del límit de taxa per usuari (30 sol·licituds / minut, codificat) que ja protegeix contra bucles descontrolats d\'un sol usuari.','Daily request limit'=>'Límit diari de sol·licituds','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'Límit màxim de sol·licituds de la IA per dia UTC (inclou tant traduccions de la barra d\'eines com revisions de blocs). El comptador es reinicia a la mitjanit UTC. Estableix a 0 per desactivar el límit.','Minimum role'=>'Rol mínim','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'Capacitat de WordPress més baixa que permet activar les funcions de la IA. Restringir això en llocs amb múltiples autors evita que Col·laboradors o comptes de prova executin trucades de IA de pagament. Sobrescriu per funció mitjançant el filtre linguaforge_required_capability.','Translation Limits'=>'Límits de traducció','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'Controla quina quantitat de contingut s\'envia a la IA i com de gran pot ser la resposta. Deixa en blanc un camp per utilitzar el valor per defecte integrat (mostrat com a espai reservat). Augmenta aquests valors si es tallen pàgines grans; redueix-los per reduir els costos de l\'API.','Model tier'=>'Nivell de model','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Qualitat (per defecte — Sonnet / GPT-4o / Gemini Pro)','Light (fast and cost-effective — Haiku / Flash)'=>'Llum (ràpid i econòmic — Haiku / Flash)','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Quin nivell de model utilitzar per a la traducció de pàgines completes. La qualitat utilitza el model configurat a la taula de models anterior i es recomana per a traduccions precises i de llarg format. Canvia a Llum només si la rapidesa o el cost són la prioritat i el contingut és curt.','Max output tokens'=>'Tokens màxims de sortida','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'Nombre màxim de tokens que la IA pot produir en una sola resposta de traducció. Si una traducció es talla silenciosament al final, augmenta aquest valor. Per defecte: 16.000.','Max input characters'=>'Caràcters d\'entrada màxims','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'Nombre màxim de caràcters del contingut de la publicació enviats a l\'IA. 0 significa sense límit — sempre s\'envia el contingut complet (recomanat). Estableix un valor diferent de zero només si el teu proveïdor té una finestra de context ajustada. Es mostra una advertència al registre d\'errors de PHP cada vegada que es retalla el contingut.','Quick Translation'=>' Traducció ràpida','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'La traducció ràpida s\'utilitza en mode fragment/pedaç — passatges curts traduïts a demanda des de la barra d\'eines, l\'editor o els popovers de blocs. Utilitza una configuració separada i més lleugera de la traducció de pàgina completa per mantenir les respostes ràpides i econòmiques.','Light (default — fast and cost-effective)'=>' Lleuger (per defecte — ràpid i econòmic)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>' Qualitat (Sonnet / GPT-4o / Gemini Pro)','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'El nivell Lleuger utilitza el model ràpid configurat a la taula de Models anterior (per defecte: Haiku / Flash). Canvia a Qualitat si necessites la mateixa precisió de traducció que en mode de pàgina completa per a fragments.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'Nombre màxim de tokens que l\'IA pot produir per traducció ràpida. Per defecte: 2.000.','Maximum characters accepted from the input field. Default: 8 000.'=>'Nombre màxim de caràcters acceptats des del camp d\'entrada. Per defecte: 8.000.','Content Generator'=>'Generador de contingut','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'Controla el pressupost de tokens i els límits d\'entrada per a la funció Generador de contingut de l\'IA. Deixa els camps en blanc per utilitzar els valors predeterminats integrats.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'Nombre màxim de tokens que l\'IA pot produir per execució de generació. Augmenta aquest valor si s\'estan tallant articles complets. Per defecte: 8.192.','Max hints characters'=>'Màxim de caràcters d\'orientació','Maximum characters read from the Hints field. Default: 2 000.'=>'Nombre màxim de caràcters llegits des del camp d\'orientacions. Per defecte: 2.000.','Max context characters'=>'Màxim de context','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'Nombre màxim de caràcters del contingut de la publicació existent passats a l\'IA com a context de llavor quan no es proporcionen orientacions. Per defecte: 6.000.','Maintenance'=>'Manteniment','Language Overrides'=>'Sobreescriptures de llengua','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Carrega arxius .mo compilats per substituir les cadenes del complement de tercers per a idiomes específics — per exemple, una traducció personalitzada de VikBooking que utilitza "apartament" en lloc de "habitació". Els arxius han de seguir la convenció de nomenament de WordPress: {textdomain}-{locale}.mo (per exemple, vikbooking-ca.mo). Es guarden a la carpeta d\'uploads i sobreviuen a les actualitzacions del complement.','Override file uploaded successfully.'=>'Arxiu de substitució carregat correctament.','Override file deleted.'=>'Arxiu de substitució eliminat.','No file was selected.'=>'No s\'ha seleccionat cap arxiu.','Only .mo files are accepted.'=>'Només s\'accepten arxius .mo.','The upload failed — please try again.'=>'La càrrega ha fallat — torna-ho a provar.','Could not save the file. Check that the uploads folder is writable.'=>'No s\'ha pogut desar l\'arxiu. Comprova que la carpeta d\'uploads sigui editable.','Invalid filename.'=>'Nom de fitxer no vàlid.','Security check failed — file path is not permitted.'=>'Fallada en la comprovació de seguretat — el camí de l\'arxiu no està permès.','An unknown error occurred.'=>'S\'ha produït un error desconegut.','Text domain / locale'=>'Àmbit de text / idioma','Files'=>'Arxius','Size'=>'Mida','Delete all files for this override (both .mo and .po)?'=>'Eliminar tots els arxius d\'aquesta substitució (tant .mo com .po)?','No override files uploaded yet.'=>'Encara no s\'han carregat arxius de substitució.','Upload .mo file'=>'Carrega arxiu .mo','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Accepta només arxius .mo compilats. El nom de l\'arxiu ha de seguir el patró {textdomain}-{locale}.mo. Carregar un arxiu amb el mateix nom que un de ja existent el substituirà.','Upload Override'=>'Carrega substitució','Loco Translate — Copy to Safe Storage'=>'Loco Translate — Copia a emmagatzematge segur','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate emmagatzema les seves traduccions personalitzades a wp-content/languages/loco/ — una ubicació que pot ser esborrada silenciosament per una actualització del nucli de WP, reinstal·lació del complement, o si Loco Translate mateix és eliminat. Copiar arxius aquí els mou a la carpeta Lingua Forge i18n-overrides, que persisteix a través de tots aquests esdeveniments i s\'carrega automàticament en cada sol·licitud.','File copied to safe storage successfully.'=>'Arxiu copiat a l\'emmagatzematge segur correctament.','Source file not found.'=>'Arxiu font no trobat.','Could not copy the file. Check that the uploads folder is writable.'=>'No s\'ha pogut copiar l\'arxiu. Comprova que la carpeta d\'uploads sigui editable.','Invalid file reference.'=>'Referència d\'arxiu no vàlida.','Type'=>'Tipus','✓ In safe storage'=>'✓ En emmagatzematge segur','Copy to safe storage'=>'Copia a emmagatzematge segur','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Encara no s\'han trobat arxius personalitzats de Loco Translate. Apareixen aquí un cop guardes una traducció a Loco Translate.','AI Cache'=>'Caché d\'IA','Lingua Forge caches AI-generated translations, meta descriptions, excerpts, and generated content per-post so unchanged inputs do not re-trigger a paid API call. Cached entries are automatically invalidated when their inputs change. Clear the cache manually to reclaim database space, force a resync after switching providers or editing prompt templates, or troubleshoot a cache-related issue.'=>'Lingua Forge desa les traduccions generades per IA, metadescripcions, extractes i contingut generat per publicació perquè les entrades sense canvis no desencadenin una trucada API de pagament. Les entrades en caché s\'invaliden automàticament quan canvien els seus inputs. Esborra la caché manualment per recuperar espai a la base de dades, forçar una sincronització després de canviar de proveïdor o editar plantilles de prompts, o per solucionar un problema relacionat amb la caché.','AI cache cleared. %d entry was removed.'=>'Caché d\'IA esborrada. %d entrada s\'ha eliminat.' . "\0" . 'Caché d\'IA esborrada. %d entrades s\'han eliminat.','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'Esborrar tots els resultats en caché d\'IA? Les sol·licituds futures desencadenaran noves trucades API fins que la caché es reconstruïsca.','Clear AI Cache'=>'Neteja la memòria cau de l\'AI','Debug Files'=>'Arxius de depuració','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'Quan s\'activa el registre de depuració (a través del commutador de sota o definint LINGUAFORGE_AI_DEBUG a wp-config.php), les funcions de traducció i de traducció de plantilles FSE escriuen les seves peticions i respostes d\'AI en brut a disc per a la resolució de problemes. Utilitza aquesta secció per monitoritzar aquesta sortida i netejar-la un cop tinguis el que necessites — els arxius poden créixer ràpidament en pàgines grans. Configura el directori de destinació mitjançant el filtre linguaforge_debug_dir.','Debug files cleared. %d file was removed.'=>'Arxius de depuració eliminats. %d arxiu s\'ha eliminat.' . "\0" . 'Arxius de depuració eliminats. %d arxius s\'han eliminat.','Debug logging enabled.'=>'Registre de depuració activat.','Debug logging disabled.'=>'Registre de depuració desactivat.','Debug logging'=>'Depuració','Write AI prompts and responses to disk for troubleshooting'=>'Escriu peticions i respostes d\'AI a disc per a la resolució de problemes','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Forçat a ON per la constant LINGUAFORGE_AI_DEBUG a wp-config.php. Elimina aquesta línia per controlar aquest commutador des d\'aquí.','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Forçat a OFF per la constant LINGUAFORGE_AI_DEBUG a wp-config.php. Elimina aquesta línia per controlar aquest commutador des d\'aquí.','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'Els arxius es guarden al directori de sota. Útil per diagnosticar problemes de traducció — desactiva-ho un cop tinguis el que necessites perquè els arxius no s\'acumulin. També pots forçar-ho des de wp-config.php amb `define( \'LINGUAFORGE_AI_DEBUG\', true );` que sobreescriu el commutador.','Currently:'=>'Actualment:','✓ Enabled'=>'✓ Activat','✗ Disabled'=>'✗ Desactivat','Directory'=>'Directori','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Filtra amb linguaforge_debug_dir per redirigir la sortida de depuració a una ubicació no pública.','.txt file(s) in the directory'=>'.txt arxiu(s) al directori','Save Debug Setting'=>' Desa la configuració de depuració','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'Eliminar tots els arxius .txt del directori de depuració? El directori en si romandrà perquè les futures escriptures de depuració també s\'hi puguin guardar.','Clear Debug Files'=>'Neteja els arxius de depuració','Per-block translation cache shared across posts. Configure on/off in Settings → Behavior. Stats below show what is currently cached; clearing forces every block to be re-translated on next request (useful after upgrading models or to recover database space).'=>'Caché de traducció per bloc compartit entre publicacions. Configura l\'activació/desactivació a Configuració → Comportament. Les estadístiques a continuació mostren el que està en caché actualment; netejar-ho obliga a que cada bloc sigui re-traduit en la propera sol·licitud (útil després d\'actualitzar models o per recuperar espai a la base de dades).','Translation Memory cleared. %d cached block was removed.'=>'Memòria de traducció netejada. %d bloc en caché s\'ha eliminat.' . "\0" . 'Memòria de traducció netejada. %d blocs en caché s\'han eliminat.','Status'=>'Estat','— toggle in Settings → Behavior.'=>'— commutador a Configuració → Comportament.','Cached blocks'=>'Blocs en caché','Cumulative cache hits'=>'Encerts acumulats en la memòria cau','(avg %.1f hits/block)'=>'(mitjana %.1f encerts/bloc)','Oldest entry'=>'Entrada més antiga','Newest entry'=>'Entrada més nova','Approximate size'=>'Mida aproximada','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'Netejar tota la Memòria de Traducció? Les traduccions futures reconstruiran la memòria cau a mesura que s\'executin.','Clear Translation Memory'=>'Neteja la Memòria de Traducció','Uninstall Behaviour'=>'Desinstal·lar comportament','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Controla què passa quan un administrador elimina el plugin des de Plugins → Plugins instal·lats → Elimina. Els ajustaments del plugin i les memòries AI sempre s\'eliminaran. Les assignacions de llengua i les relacions de traducció es mantenen per defecte perquè una desinstal·lació accidental o una reinstal·lació puguin continuar on ho van deixar.','Uninstall setting saved.'=>'Configuració de desinstal·lació guardada.','Delete content data on uninstall'=>'Eliminar dades de contingut en desinstal·lació','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'També elimina les assignacions de llengua, relacions de traducció, metadescripcions, glossari i Memòria de Traducció quan s\'elimina el plugin.','Warning:'=>'Avís:','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'Si està marcat, la desinstal·lació del plugin eliminarà permanentment totes les assignacions de llengua, relacions de traducció, metadescripcions, presets per pàgina, el glossari AI i la Memòria de Traducció de cada publicació d\'aquest lloc. Això no es pot desfer. Deixa-ho desmarcat a menys que estiguis eliminant completament el suport multilingüe del lloc.','Save Uninstall Setting'=>'Desa la configuració de desinstal·lació','Router'=>'Router','Primary language saved.'=>'Llengua principal guardada.','Permalink rules flushed successfully.'=>'Les regles de permalinks s\'han buidat correctament.','Primary Language'=>'Llengua principal','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'La llengua principal sempre s\'ofereix a la ruta arrel del teu lloc — sense prefix URL en mode de ruta, sense subdomini de llengua en mode de subdomini. Totes les altres llengües utilitzen un prefix /lang/ (p. ex. example.com/de/) o un subdomini de llengua (p. ex. de.exemple.com), segons l\'ajust de l\'estructura d\'URL a sota.','Primary language'=>'Llengua principal','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'Després de canviar la llengua principal, buida els permalinks (secció a sota) perquè s\'actualitzi la rutes d\'URL.','URL structure'=>'Estructura d\'URL','Path prefix — example.com/de/'=>'Prefix de camí — example.com/ca/','Subdomain — de.example.com/'=>'Subdomini — ca.exemple.com/','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'El mode de subdomini requereix que el teu servidor web apunti tots els subdominis de llengua (per exemple, ca.exemple.com) a aquesta instal·lació de WordPress. Després de canviar de mode, buida les regles de permalinks i elimina qualsevol memòria cau. Si la teva URL d\'inici inclou www (per exemple, www.exemple.com), utilitza el filtre lf_base_domain per establir el domini apex sense subdomini perquè els subdominis es construeixin correctament.','Browser language redirect'=>'Redirecció de llengua del navegador','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Redirigeix els visitants a la seva llengua preferida segons l\'encapçalament Accept-Language del navegador','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'Quan està activat, els visitants que no tenen cookie de llengua i no tenen prefix de llengua a l\'URL són redirigits a la versió de llengua més propera. La redirecció s\'ignora si la llengua preferida del navegador no està entre les llengües actives del router. Un cop un visitant selecciona una llengua mitjançant el commutador, la cookie té prioritat i s\'ignora l\'encapçalament del navegador en futures visites.','Save Router Settings'=>'Desa la configuració del router','Flush Permalinks'=>'Buida els permalinks','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'Regenera les regles de reescriptura de WordPress perquè els prefixos d\'URL, els slugs específics de la llengua i les reescriptures d\'arxiu estiguin sincronitzats. És necessari després de canviar la llengua principal o afegir suport per a una nova llengua.','Flush Permalink Rules'=>'Buida les regles de permalinks','Active Languages'=>'Llengües actives','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'Llengües actualment conegudes pel router (derivades dels paquets de llengua de WordPress instal·lats més la llengua principal). Instal·la paquets de llengua addicionals a la secció de sota per fer més llengües disponibles per a la ruta i la traducció.','%d locale pack installed.'=>'%d paquet de llengua instal·lat.' . "\0" . '%d paquets de llengua instal·lats.','Install a Language'=>'Instal·la una llengua','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'Descarrega i instal·la un paquet de llengua del nucli de WordPress directament des de WordPress.org. Un cop instal·lat, la llengua esdevé disponible per a la ruta d\'URL i el flux de treball de traducció AI. La llista de llengües disponibles es recupera a demanda — fes clic al botó de sota per carregar-la.','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'La instal·lació de llengües està desactivada en aquest servidor. La constant DISALLOW_FILE_MODS està establerta en wp-config.php. Installa els paquets de llengua manualment via WP-CLI: wp language core install ca_DE','Load available languages'=>'Carrega les llengües disponibles','— select a language —'=>'— selecciona una llengua —','Install'=>'Instal·la','Language Setup'=>'Configuració de la llengua','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'Cap llengua secundària configurada. Instal·la un paquet de llengua a dalt per habilitar l\'esquelet de la plantilla.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Selecciona una llengua per gestionar les seves plantilles FSE, parts de la plantilla i menús de navegació.','Forbidden'=>'Prohibit','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'La instal·lació de llengües està desactivada en aquest servidor (DISALLOW_FILE_MODS està establert).','Invalid locale code.'=>'Codi de llengua no vàlid.','Language %s installed successfully.'=>'La llengua %s s\'ha instal·lat correctament.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'La instal·lació del paquet de llengua ha fallat. La llengua ja pot estar instal·lada, el codi de llengua pot ser incorrecte, o el teu servidor pot bloquejar l\'escriptura de fitxers.','Navigations'=>'Navegacions','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'La traducció de navegació requereix un proveïdor d\'AI actiu. Configura una clau API a la pestanya de Claves API.','Navigation'=>'Navegació','Action'=>'Acció','Re-translate'=>'Re-tradueix','CPT Block Patterns'=>'Patrons de blocs CPT','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'Patrons de blocs registrats per a tipus de publicació personalitzats. Utilitza el botó de Traducció per produir una variant de llengua. El contingut traduït s\'emmagatzema aquí i pot ser copiat a qualsevol publicació CPT des de l\'inseridor de patrons de l\'editor de blocs o utilitzat com a punt de partida per a un Patró sincronitzat (Bloc reutilitzable).','Pattern'=>'Patró','Post Types'=>'Tipus de publicació','✓ Translation saved'=>'✓ Traducció desada','View'=>'Veure','Template Parts'=>'Parts de la plantilla','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'Còpies específiques de la llengua de les parts de la plantilla del tema. Un cop esbós, les plantilles s\'actualitzen per referenciar la part específica de la llengua.','Part'=>'Part','Status / Actions'=>'Estat / Accions','Fix Links'=>'Corregir enllaços','Fix Nav'=>'Corregir navegació','Create'=>'Crear','Templates'=>'Plantilles','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'Les plantilles FSE s\'inicialitzen des del tema actiu. Crea-les i personalitza-les al Editor del lloc.','Actions'=>'Accions','Fix Parts'=>'Corregir parts','Create missing'=>'Crear missing','Translate all'=>'Tradueix tot','Fix all parts'=>'Arregla totes les parts','Fix all links'=>'Arregla tots els enllaços','Anthropic (Claude)'=>'Anthropic (Claude)','OpenAI (GPT)'=>'OpenAI (GPT)','Google (Gemini)'=>'Google (Gemini)','Testing…'=>'Prova…','✓ Connection OK'=>'✓ Connexió OK','✗ Failed:'=>'✗ Fallat:','No response from provider — check the error log for details.'=>'No hi ha resposta del proveïdor — revisa el registre d\'errors per a més detalls.','Network error — could not reach the WordPress AJAX endpoint.'=>'Error de xarxa — no s\'ha pogut arribar a l\'endpoint AJAX de WordPress.','Loading…'=>'Carregant…','Installing…'=>'Estan instal·lant…','✓ Language installed.'=>'✓ Idioma instal·lat.','✗ Error:'=>'✗ Error:','Creating…'=>'Creant…','✓ All templates created.'=>'✓ Totes les plantilles creades.','Some templates could not be created.'=>'Algunes plantilles no s\'han pogut crear.','✓ All parts created.'=>'✓ Totes les parts creades.','Some parts could not be created.'=>'Algunes parts no s\'han pogut crear.','✓ All translated.'=>'✓ Totes traduïdes.','Some translations failed.'=>'Algunes traduccions han fallat.','Review carefully — links and slugs not updated.'=>'Revisa atentament — enllaços i slugs no actualitzats.','Fixing…'=>'Arreglant…','✓ Links fixed.'=>'✓ Enllaços arreglats.','Some link fixes failed.'=>'Alguns arreglaments d\'enllaços han fallat.','✓ Parts fixed.'=>'✓ Parts arreglades.','Some part fixes failed.'=>'Alguns arreglaments de parts han fallat.','✓ Nav refs fixed.'=>'✓ Referències de navegació arreglades.','Some nav ref fixes failed.'=>'Alguns arreglaments de referèn